var a=[{title:`Erőfeszítés és ártalom`,text:`Az izomfáradtság, a nehéz légzés és az átmeneti égő érzés együtt járhat a kemény mozgással. Az éles fájdalom, az új ízületi kellemetlenség, a szétterjedő fájdalom vagy a szédülés nem teljesítmény. A tested akkor alkalmazkodik, ha egy kemény, de elviselhető edzést elegendő regeneráció követ. A fájdalom nem az, amitől működik.`},{title:`Az izomláz rossz pontszám`,text:`A késleltetett izomláz különösen gyakori ismeretlen vagy kemény mozgás után. Gyakran elmúlik, ahogy a tested hozzászokik egy mozdulathoz, miközben az erőd és az erőnléted tovább javul. Egy olyan edzés, amely után alig fáj az izmod, még lehet eredményes, a túl sok izomláz pedig megnehezítheti a rendszeres edzést.`},{title:`Haladás büntetés nélkül`,text:`Olyan ismétléseket válassz, amelyek kihívást jelentenek, de kontrolláltak, fokozatosan emeld az edzésigényeket, és iktass be pihenő- vagy könnyebb napokat. Értelmes lehet egy sorozatot néhány tartalék ismétléssel befejezni. A kutatás nem mutatja, hogy az átlagos egészséges felnőttnek újra és újra el kellene érnie az izomkimerülést ahhoz, hogy értékes eredményeket kapjon.`},{title:`Példa`,text:`Egy kezdő, aki heti két egész testes edzést végez, és folyamatosan növeli a guggolás- és fekvőtámasz-ismétléseket, fejlődhet anélkül, hogy minden edzés után kivéreznének.`},{title:`A TrainUp használata`,text:`Edzés után értékeled az edzés erőfeszítését (RPE), és jelzed a fájdalmat a testtáj és a gyakorlat megadásával. Ha edzés közben valami fáj, használd a „Fájdalmat érzek” gombot, hogy azonnal véget érjen a gyakorlat; addig nem kerül a terveidbe, amíg a Profilban vissza nem kapcsolod. Bármilyen friss fájdalom esetén a következő terved nem lesz nehezebb. Az új vagy súlyos fájdalom ok arra, hogy megállj, és megvizsgáltasd.`}];var s=[{label:`2026-os ACSM állásfoglalás`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`ACSM 2026-os gyakorlati útmutató`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: ízületi fájdalom`,url:`https://www.nhs.uk/symptoms/joint-pain/`}];var l={sections:a,sources:s};export{l as default,a as sections,s as sources};